package gitproto

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"testing"
)

// craft a pack whose single object declares an enormous size
func craftPack(sizeBytes []byte) []byte {
	var b bytes.Buffer
	b.WriteString("PACK")
	binary.Write(&b, binary.BigEndian, uint32(2))
	binary.Write(&b, binary.BigEndian, uint32(1))
	b.Write(sizeBytes)
	b.Write([]byte{0x78, 0x9c, 0x03, 0x00, 0x00, 0x00, 0x00, 0x01}) // empty zlib stream
	b.Write(make([]byte, 20))                                      // trailer
	return b.Bytes()
}

func TestZZHugeDeclaredSize(t *testing.T) {
	// type=commit(1), MSB set, then continuation bytes -> giant size
	hdr := []byte{0x9F, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x7F}
	pack := craftPack(hdr)
	fmt.Printf("pack len=%d\n", len(pack))
	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("PANIC: %v\n", r)
		}
	}()
	_, err := ExtractCommitParents(bytes.NewReader(pack))
	fmt.Printf("returned err=%v\n", err)
}
