package gitproto

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"runtime"
	"testing"
)

func craftPack(hdr []byte) []byte {
	var b bytes.Buffer
	b.WriteString("PACK")
	binary.Write(&b, binary.BigEndian, uint32(2))
	binary.Write(&b, binary.BigEndian, uint32(1))
	b.Write(hdr)
	b.Write([]byte{0x78, 0x9c, 0x03, 0x00, 0x00, 0x00, 0x00, 0x01})
	b.Write(make([]byte, 20))
	return b.Bytes()
}

// encodeObjHeader encodes a pack object header for the given type and size.
func encodeObjHeader(typ byte, size uint64) []byte {
	first := (typ&7)<<4 | byte(size&0x0f)
	size >>= 4
	var out []byte
	for size > 0 {
		out = append(out, first|0x80)
		first = byte(size & 0x7f)
		size >>= 7
	}
	out = append(out, first)
	return out
}

func TestZZHugeDeclaredSize2(t *testing.T) {
	for _, sz := range []uint64{1 << 30, 1 << 36} {
		hdr := encodeObjHeader(1, sz)
		pack := craftPack(hdr)
		fmt.Printf("--- declared size=%d GiB, pack bytes=%d, header=%x\n", sz>>30, len(pack), hdr)
		var before, after runtime.MemStats
		runtime.ReadMemStats(&before)
		func() {
			defer func() {
				if r := recover(); r != nil {
					fmt.Printf("    PANIC: %v\n", r)
				}
			}()
			_, err := ExtractCommitParents(bytes.NewReader(pack))
			fmt.Printf("    err=%v\n", err)
		}()
