17	// ExtractCommitParents. Sized to comfortably cover delta locality for
18	// tree:0-filtered packs generated with git's default window/depth
19	// (typically tens of objects of working set).
20	const DefaultCommitParentsCacheBytes = 64 * 1024 * 1024
21	
22	// ExtractCommitParents reads a Git packfile from r and returns a map
23	// of commit hash → parent hashes for every commit object encountered.
24	// Non-commit objects (tags, etc.) and the raw bytes of commits are
25	// discarded after parent extraction, so peak memory is dominated by
26	// the result map plus a small bounded delta-resolution cache.
27	//
28	// Intended for tree:0-filtered packs where the only object kinds are
29	// commits and (occasionally) annotated tags. Input is the raw packfile
30	// stream (e.g. demuxed sideband from a v2 fetch response).
31	func ExtractCommitParents(r io.Reader) (map[plumbing.Hash][]plumbing.Hash, error) {
32		return ExtractCommitParentsWithCache(r, DefaultCommitParentsCacheBytes)
33	}
34	
35	// ExtractCommitParentsWithCache is like ExtractCommitParents but lets
36	// the caller cap the delta-resolution cache size. On cache miss the
37	// underlying pack parser returns ErrObjectNotFound; raise the limit
38	// and retry, or fall back to the in-memory store path.
39	func ExtractCommitParentsWithCache(r io.Reader, maxCacheBytes int) (map[plumbing.Hash][]plumbing.Hash, error) {
40		if maxCacheBytes <= 0 {
41			maxCacheBytes = DefaultCommitParentsCacheBytes
42		}
43	
44		// go-git's pack parser forces lowMemoryMode = false when the input
45		// is not seekable (parser.go:83-85), which causes the scanner to
46		// buffer every inflated object in memory until Parse returns
47		// (scanner.go:427) — undoing the savings the custom storer aims
48		// for. We spill the pack to a temp file so the parser sees a
49		// seekable source, enables low-memory mode, and releases object
50		// content as it flows through the storer. Already-seekable inputs
51		// (e.g. tests using bytes.Reader) skip the spill.
52		seekable, ok := r.(io.ReadSeeker)
53		if !ok {
