55			if err != nil {
56				return nil, fmt.Errorf("create temp pack: %w", err)
57			}
58			defer os.Remove(tmp.Name())
59			defer tmp.Close()
60	
61			if _, err := io.Copy(tmp, r); err != nil {
62				return nil, fmt.Errorf("spill pack to temp: %w", err)
63			}
64			if _, err := tmp.Seek(0, io.SeekStart); err != nil {
65				return nil, fmt.Errorf("seek temp pack: %w", err)
