101		parts := strings.SplitN(raw, ":", 2)
102		if len(parts) != 2 {
103			return RefMapping{}, fmt.Errorf("invalid --map %q, expected src:dst", raw)
104		}
105		source := strings.TrimSpace(parts[0])
106		target := strings.TrimSpace(parts[1])
107		if source == "" || target == "" {
108			return RefMapping{}, fmt.Errorf("invalid --map %q, expected src:dst", raw)
109		}
110		return RefMapping{Source: source, Target: target}, nil
111	}
112	
113	// ParseHaveRef normalizes a have-ref CLI value. Short names are treated as
114	// branch names for compatibility with other CLI ref selectors.
115	func ParseHaveRef(raw string) plumbing.ReferenceName {
116		raw = strings.TrimSpace(raw)
117		if strings.HasPrefix(raw, "refs/") {
118			return plumbing.ReferenceName(raw)
119		}
120		return plumbing.NewBranchReferenceName(raw)
121	}
122	
123	// NormalizeMapping validates a single mapping. allowOther accepts
124	// refs/* outside refs/heads/ and refs/tags/.
125	func NormalizeMapping(m RefMapping, allowOther bool) (NormalizedMapping, error) {
126		src := strings.TrimSpace(m.Source)
127		dst := strings.TrimSpace(m.Target)
128		if src == "" || dst == "" {
129			return NormalizedMapping{}, fmt.Errorf("invalid mapping %q:%q: source and target must be non-empty", m.Source, m.Target)
130		}
131	
132		srcFQ := strings.HasPrefix(src, "refs/")
133		dstFQ := strings.HasPrefix(dst, "refs/")
134	
135		if srcFQ && dstFQ {
136			sourceRef := plumbing.ReferenceName(src)
137			targetRef := plumbing.ReferenceName(dst)
138			if err := validateRefName("source", sourceRef); err != nil {
139				return NormalizedMapping{}, err
140			}
141			if err := validateRefName("target", targetRef); err != nil {
142				return NormalizedMapping{}, err
143			}
144			srcKind := refKind(sourceRef)
145			dstKind := refKind(targetRef)
146			if !allowOther && srcKind == kindOther {
147				return NormalizedMapping{}, fmt.Errorf("unsupported source ref kind: %s (set --all-refs to allow arbitrary refs/* namespaces)", src)
148			}
149			if !allowOther && dstKind == kindOther {
150				return NormalizedMapping{}, fmt.Errorf("unsupported target ref kind: %s (set --all-refs to allow arbitrary refs/* namespaces)", dst)
151			}
152			if srcKind != dstKind {
153				return NormalizedMapping{}, fmt.Errorf("cross-kind mapping not allowed: %s (%s) -> %s (%s)", src, srcKind, dst, dstKind)
154			}
155			return NormalizedMapping{SourceRef: sourceRef, TargetRef: targetRef}, nil
156		}
157	
158		if !srcFQ && !dstFQ {
159			sourceRef := plumbing.NewBranchReferenceName(src)
160			targetRef := plumbing.NewBranchReferenceName(dst)
161			if err := validateRefName("source", sourceRef); err != nil {
162				return NormalizedMapping{}, err
163			}
164			if err := validateRefName("target", targetRef); err != nil {
165				return NormalizedMapping{}, err
166			}
167			return NormalizedMapping{SourceRef: sourceRef, TargetRef: targetRef}, nil
168		}
169	
170		return NormalizedMapping{}, fmt.Errorf("ambiguous mapping: cannot mix fully-qualified and short ref names: %q -> %q", src, dst)
171	}
172	
173	// ValidateMappings normalizes all mappings and rejects duplicate target refs.
174	func ValidateMappings(mappings []RefMapping, allowOther bool) ([]NormalizedMapping, error) {
175		if len(mappings) == 0 {
176			return nil, nil
177		}
178	
179		normalized := make([]NormalizedMapping, 0, len(mappings))
180		targetSeen := make(map[plumbing.ReferenceName]string, len(mappings))
181	
182		for _, m := range mappings {
183			nm, err := NormalizeMapping(m, allowOther)
184			if err != nil {
185				return nil, err
186			}
187			if prev, exists := targetSeen[nm.TargetRef]; exists {
188				return nil, fmt.Errorf("duplicate target ref %s: mapped from both %q and %q", nm.TargetRef, prev, m.Source)
189			}
190			targetSeen[nm.TargetRef] = m.Source
191			normalized = append(normalized, nm)
192		}
193		return normalized, nil
194	}
195	
196	// validateRefName rejects a mapping ref name that git itself would not accept.
197	//
198	// A mapped target ref reaches the same places an advertised one does — written
199	// to disk by convert-sha256, embedded in receive-pack command lines — so a name
200	// containing "..", NUL, or control characters carries the same risk regardless
201	// of whether a remote or a caller supplied it. Unlike advertised names, which
202	// are skipped so one bad ref upstream cannot stop a mirror, a bad mapping is
203	// rejected outright: it is configuration, and failing at startup is more useful
204	// than silently not mirroring what was asked for.
205	func validateRefName(side string, name plumbing.ReferenceName) error {
206		if err := name.Validate(); err != nil {
207			return fmt.Errorf("invalid %s ref %q in mapping: %w", side, name.String(), err)
208		}
209		return nil
210	}
211	
212	const (
213		kindBranch = "branch"
214		kindTag    = "tag"
215		kindOther  = "other"
216	)
217	
218	func refKind(name plumbing.ReferenceName) string {
219		switch {
220		case name.IsBranch():
221			return kindBranch
222		case name.IsTag():
223			return kindTag
224		case strings.HasPrefix(name.String(), "refs/"):
225			return kindOther
226		default:
227			return ""
228		}
229	}

